// Minimal re-implementation of the subset of Python's argparse behaviour
// used by the source script: required integer options, --opt value and
// --opt=value forms, -h/--help, and argparse-compatible error reporting.
import { basename } from 'node:path';

const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;
const INT_RE = /^[+-]?\d(?:_?\d)*$/;

function looksLikeOption(token) {
  // A token starting with '-' is treated as an option string, unless it
  // looks like a negative number (the parser has no number-like options).
  return (
    token.length > 1 &&
    token.startsWith('-') &&
    !NEGATIVE_NUMBER_RE.test(token)
  );
}

function parsePythonInt(raw) {
  const trimmed = raw.trim();
  if (!INT_RE.test(trimmed)) {
    return null;
  }
  return parseInt(trimmed.replace(/_/g, ''), 10);
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    // Ordered option definitions: { name, metavar, required }
    this.options = [];
  }

  addIntArgument(name, { required = false } = {}) {
    this.options.push({
      name,
      metavar: name.slice(2).toUpperCase(),
      required,
    });
  }

  usageLine() {
    const parts = [`usage: ${this.prog}`, '[-h]'];
    for (const opt of this.options) {
      parts.push(opt.required ? `${opt.name} ${opt.metavar}` : `[${opt.name} ${opt.metavar}]`);
    }
    return parts.join(' ');
  }

  printHelp() {
    const lines = [this.usageLine(), '', 'options:', '  -h, --help  show this help message and exit'];
    for (const opt of this.options) {
      lines.push(`  ${opt.name} ${opt.metavar}`);
    }
    process.stdout.write(lines.join('\n') + '\n');
  }

  error(message) {
    process.stderr.write(this.usageLine() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv) {
    const values = {};
    for (const opt of this.options) {
      values[opt.name.slice(2)] = undefined;
    }
    const extras = [];
    const seen = new Set();

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];

      if (token === '-h' || token === '--help') {
        this.printHelp();
        process.exit(0);
      }

      let name = token;
      let inlineValue = null;
      if (token.startsWith('--') && token.includes('=')) {
        const eq = token.indexOf('=');
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      const opt = this.options.find((o) => o.name === name);
      if (opt && looksLikeOption(name)) {
        seen.add(opt.name);
        let raw;
        if (inlineValue !== null) {
          raw = inlineValue;
        } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
          raw = argv[i + 1];
          i += 1;
        } else {
          this.error(`argument ${opt.name}: expected one argument`);
        }
        const parsed = parsePythonInt(raw);
        if (parsed === null) {
          this.error(`argument ${opt.name}: invalid int value: '${raw}'`);
        }
        values[opt.name.slice(2)] = parsed;
      } else {
        extras.push(token);
      }
      i += 1;
    }

    const missing = this.options
      .filter((o) => o.required && !seen.has(o.name))
      .map((o) => o.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

export function createParserFromArgv(argv = process.argv) {
  const prog = basename(argv[1] || 'test11.mjs');
  const parser = new ArgumentParser(prog);
  return { parser, args: argv.slice(2) };
}

// Job mirrors the behaviour of schedule.Job as exercised by the source
// script: unit selection via property access (.seconds, .minutes, ...),
// .tag(...) for labelling, and .do(fn) for registering the job.

const UNITS = ['second', 'minute', 'hour', 'day', 'week'];

export class Job {
  constructor(scheduler, interval) {
    this.scheduler = scheduler;
    this.interval = interval;
    this.unit = null;
    this.tags = new Set();
    this.jobFunc = null;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  tag(...tags) {
    for (const t of tags) {
      this.tags.add(t);
    }
    return this;
  }

  do(jobFunc) {
    if (!UNITS.some((u) => this.unit === u || this.unit === `${u}s`)) {
      // The source script always selects a unit before .do(); kept for parity.
    }
    this.jobFunc = jobFunc;
    this.scheduler.addJob(this);
    return this;
  }

  // runPending / actual scheduling are out of scope: the source script only
  // creates, tags, counts and clears jobs.
}

// Scheduler mirrors the module-level API of the Python `schedule` package
// as used by the source script: every(), get_jobs() and clear() operating
// on a default scheduler instance.
import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  every(interval = 1) {
    return new Job(this, interval);
  }

  addJob(job) {
    if (!this.jobs.includes(job)) {
      this.jobs.push(job);
    }
  }

  getJobs(tag = undefined) {
    if (tag === undefined || tag === null) {
      return [...this.jobs];
    }
    return this.jobs.filter((job) => job.tags.has(tag));
  }

  clear(tag = undefined) {
    if (tag === undefined || tag === null) {
      this.jobs = [];
    } else {
      this.jobs = this.jobs.filter((job) => !job.tags.has(tag));
    }
  }
}

// Default scheduler, mirroring schedule's global default_scheduler.
export const defaultScheduler = new Scheduler();

export function every(interval = 1) {
  return defaultScheduler.every(interval);
}

export function getJobs(tag = undefined) {
  return defaultScheduler.getJobs(tag);
}

export function clear(tag = undefined) {
  defaultScheduler.clear(tag);
}

// Node.js (ESM) port of /workspace/dataset/schedule/test11.py
import { createParserFromArgv } from './lib/argparse.mjs';
import { every, getJobs, clear } from './lib/scheduler/scheduler.mjs';

const { parser, args: argv } = createParserFromArgv(process.argv);
parser.addIntArgument('--a', { required: true });
parser.addIntArgument('--b', { required: true });
const args = parser.parseArgs(argv);

// 创建多个作业并测试标签过滤
let jobsCreated = 0;
for (let i = 0; i < args.a; i++) {
  every(1).seconds.tag('group1').do(() => null); // 创建group1标签作业
  jobsCreated += 1;
}
console.log(jobsCreated);

for (let i = 0; i < args.b; i++) {
  every(1).minutes.tag('group2').do(() => null); // 创建group2标签作业
  jobsCreated += 1;
}
console.log(jobsCreated);

const group1Jobs = getJobs('group1'); // 获取group1作业
console.log(group1Jobs.length);

const group2Jobs = getJobs('group2'); // 获取group2作业
console.log(group2Jobs.length);

const allJobs = getJobs(); // 获取所有作业
console.log(allJobs.length);

clear('group1'); // 清除group1作业
console.log(getJobs().length);

clear('group2'); // 清除group2作业
console.log(getJobs().length);

for (let i = 0; i < args.a + args.b; i++) { // 重新创建作业
  every(1).seconds.do(() => null);
}
console.log(getJobs().length);

